// Builder unit tests for the loader's file and source checks (ARC-8, W00a): exact issues, never a raw ENOENT.
import { copyFileSync, cpSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterAll, beforeEach, describe, expect, it } from 'vitest'
import { SAMPLE_ROOT, clientFolders, loadClient } from './load'
import { TestWorldLoadError, type LoadIssue } from '../model/schema'

const folders = clientFolders()
const home = folders.get('C01')
if (home === undefined) throw new Error('fixture: no C01')
const name = home.slice(home.lastIndexOf('/') + 1)
const roots: string[] = []
let root = ''
let folder = ''
beforeEach(() => {
  root = mkdtempSync(join(tmpdir(), 'w00a-load-'))
  roots.push(root)
  cpSync(join(SAMPLE_ROOT, name), join(root, name), { recursive: true })
  folder = join(root, name)
})
afterAll(() => {
  for (const r of roots) rmSync(r, { recursive: true, force: true })
})

type Key = { accounts: { key: string; file: string; qboFile: string }[]; adjustingEntries: { id: string; source: { transactions: string[]; onboarding: string[] } }[] }
const editJson = (file: string, edit: (j: Record<string, unknown>) => void): void => {
  const p = join(folder, file)
  const j = JSON.parse(readFileSync(p, 'utf8')) as Record<string, unknown>
  edit(j)
  writeFileSync(p, JSON.stringify(j))
}
const issues = (): LoadIssue[] => {
  try {
    loadClient('C01', { root })
  } catch (e) {
    if (e instanceof TestWorldLoadError) return e.issues
    throw e
  }
  return []
}
const firstKey = (): string => {
  const k = JSON.parse(readFileSync(join(folder, 'answer-key.json'), 'utf8')) as Key
  return k.accounts[0]?.key ?? ''
}
const issue = (check: LoadIssue['check'], record: string, reason: string): LoadIssue => ({ client: 'C01', check, record, reason })
/** W00c fix 5: a path outside accounts/*.csv or qbo/*.csv is refused before the outside-the-folder check, so the reason is left to the build; it names the path. */
const fileRefused = (record: string, value: string): LoadIssue[] => [{ client: 'C01', check: 'file', record, reason: expect.stringContaining(value) as string }]

describe('ARC-8 W00a missing client files', () => {
  it('a client with both files loads', () => {
    expect(issues()).toEqual([])
  })
  it('a missing onboarding.json is one file issue and nothing more', () => {
    rmSync(join(folder, 'onboarding.json'))
    expect(issues()).toEqual([issue('file', 'onboarding.json', 'the file is not in the client folder')])
  })
})

describe('ARC-8 W00a account files stay inside the client folder', () => {
  const setFile = (field: 'file' | 'qboFile', value: string): void => {
    editJson('answer-key.json', (j) => {
      const a = (j as unknown as Key).accounts[0]
      if (a !== undefined) a[field] = value
    })
  }
  it.each(['file', 'qboFile'] as const)('%s leading out by "../" is refused with its record and reason', (field) => {
    writeFileSync(join(root, 'x.csv'), 'a\n')
    setFile(field, '../x.csv')
    expect(issues()).toEqual(fileRefused(`${firstKey()} ${field}`, '../x.csv'))
  })
  it('the parent folder itself ("..") is outside', () => {
    setFile('file', '..')
    expect(issues()).toEqual(fileRefused(`${firstKey()} file`, '..'))
  })
  it('an absolute path is outside', () => {
    setFile('qboFile', join(root, 'x.csv'))
    expect(issues()).toEqual(fileRefused(`${firstKey()} qboFile`, join(root, 'x.csv')))
  })
  it('a file name that merely starts with two dots is inside', () => {
    const k = JSON.parse(readFileSync(join(folder, 'answer-key.json'), 'utf8')) as Key
    copyFileSync(join(folder, k.accounts[0]?.file ?? ''), join(folder, 'accounts/..data.csv'))
    setFile('file', 'accounts/..data.csv')
    expect(issues()).toEqual([])
  })
  it('a file that is not there names the account, the field and the file', () => {
    setFile('file', 'accounts/nope.csv')
    expect(issues()).toEqual([issue('file', `${firstKey()} file`, 'accounts/nope.csv is not in the client folder')])
  })
  it('a link that leads out of the folder is refused, for a file and for the parent folder', () => {
    writeFileSync(join(root, 'outside.csv'), 'a\n')
    symlinkSync(join(root, 'outside.csv'), join(folder, 'accounts/link.csv'))
    setFile('file', 'accounts/link.csv')
    expect(issues()).toEqual([issue('file', `${firstKey()} file`, 'accounts/link.csv leads out of the client folder')])
    symlinkSync(root, join(folder, 'accounts/up.csv'))
    setFile('file', 'accounts/up.csv')
    expect(issues()).toEqual(fileRefused(`${firstKey()} file`, 'accounts/up.csv'))
  })
  it('a link that stays inside the folder is fine', () => {
    const k = JSON.parse(readFileSync(join(folder, 'answer-key.json'), 'utf8')) as Key
    symlinkSync(join(folder, k.accounts[0]?.file ?? ''), join(folder, 'accounts/inside.csv'))
    setFile('file', 'accounts/inside.csv')
    expect(issues()).toEqual([])
  })
})

describe('ARC-8 W00a adjusting entry sources', () => {
  const withSource = (source: string): LoadIssue[] => {
    editJson('answer-key.json', (j) => {
      const e = (j as unknown as Key).adjustingEntries[0]
      if (e !== undefined) e.source.onboarding = [source]
    })
    return issues().filter((i) => i.check === 'adjusting-entry')
  }
  const firstEntry = (): string => (JSON.parse(readFileSync(join(folder, 'answer-key.json'), 'utf8')) as Key).adjustingEntries[0]?.id ?? ''
  it('a source naming a top-level key resolves', () => {
    // W00c fix 3: a free note in brackets no longer resolves; a qualifier must name a record (acceptance RC2).
    expect(withSource('corporation')).toEqual([])
  })
  it('a note not at the end does not resolve; the whole text is the key', () => {
    // W00c round 3 (reports/W00c-findings-3.md fix 2, A450): onboarding.json is read strictly, so no key is added;
    // "serv(x)ices" would be the existing key "services" if the note were cut out of the middle.
    for (const s of ['corporation (x) (y)', 'serv(x)ices']) {
      expect(withSource(s), s).toEqual([issue('adjusting-entry', firstEntry(), `its source "${s}" is not in onboarding.json`)])
    }
  })
  it('an unknown transaction source is named', () => {
    editJson('answer-key.json', (j) => {
      const e = (j as unknown as Key).adjustingEntries[0]
      if (e !== undefined) e.source.transactions = ['NOPE']
    })
    expect(issues().filter((i) => i.check === 'adjusting-entry')).toEqual([issue('adjusting-entry', firstEntry(), 'its source "NOPE" is not a transaction of this client')])
  })
  it('a statement balance key for an undeclared account is named', () => {
    editJson('answer-key.json', (j) => {
      ;(j['statementBalances'] as Record<string, unknown>)['XTEST'] = []
    })
    expect(issues()).toEqual([issue('roll', 'XTEST', 'it has statement balances but the answer key declares no such account')])
  })
})

describe('ARC-8 W00a fault markers reach the model', () => {
  it('only a marked row carries dupOf or priorYear', () => {
    const c10 = loadClient('C10')
    const dup = c10.transactions.filter((t) => t.dupOf !== undefined)
    expect(dup.map((t) => t.id)).toEqual(['10-CHQ-2025-03-0009', '10-CHQ-2025-03-0011', '10-CHQ-2025-03-0049', '10-CHQ-2025-03-0053'].map((id) => dup.find((t) => t.id === id)?.id))
    expect(c10.transactions.filter((t) => t.priorYear === true)).toHaveLength(8)
    const plain = c10.transactions.find((t) => t.dupOf === undefined && t.priorYear === undefined)
    expect(plain).toBeDefined()
    expect(Object.hasOwn(plain ?? {}, 'dupOf')).toBe(false)
    expect(Object.hasOwn(plain ?? {}, 'priorYear')).toBe(false)
  })
})

testworld/clients/reserved-keys.acceptan.source:
// W00c acceptance tests (round 3), RC-A fix 1: a prototype name written as a JSON key is found by a pure scanner
// exported from testworld/clients/json-keys.ts, beside repeatedKeys (reports/W00c-findings-3.md; W00b imports both).
//
// What the W00c round 3 build provides:
//   `reservedKeys(text: string): readonly { key: string }[]` (more fields allowed): every key of any object, at any
//   depth, that is "__proto__", "constructor" or "prototype" after JSON string escapes are decoded, once per
//   occurrence, in the order they are written; [] when there is none. Text inside a string value is never a key, and a
//   key that only contains one of the names is not one. `repeatedKeys` keeps its signature. The loader turns each one
//   into a 'file' issue (strict-read.acceptance.test.ts).
//
// The sample cases come from the walk over every numbered folder (sample-walk.ts). The module is loaded by a dynamic
// import so the suite type-checks before the build; until then each test fails with "exports reservedKeys".
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, test } from 'vitest'
import { SAMPLE_ROOT, walkClients } from '../model/__fixtures__/sample-walk'
import { genericOf, pattern } from '../model/__fixtures__/w00c-r3-walk'
import { objectNodes } from '../model/__fixtures__/w00c-walk'

type Scan = (text: string) => readonly { key: string }[]
async function scanners(): Promise<{ reservedKeys: Scan; repeatedKeys: Scan }> {
  const specifier = './json-keys'
  const mod = (await import(/* @vite-ignore */ specifier)) as { reservedKeys?: unknown; repeatedKeys?: unknown }
  expect(typeof mod.reservedKeys, 'testworld/clients/json-keys.ts exports reservedKeys').toBe('function')
  expect(typeof mod.repeatedKeys, 'testworld/clients/json-keys.ts still exports repeatedKeys').toBe('function')
  return { reservedKeys: mod.reservedKeys as Scan, repeatedKeys: mod.repeatedKeys as Scan }
}
const keysOf = (found: readonly { key: string }[]): string[] => found.map((r) => r.key)
const clients = walkClients()
const NAMES = ['__proto__', 'constructor', 'prototype'] as const

describe('W00c RC-A reservedKeys', () => {
  test.each(clients.map((c): [string, string] => [c.id, c.folder]))('END-9 %s: neither sample file has a reserved key', async (_id, folder) => {
    const { reservedKeys } = await scanners()
    for (const f of ['answer-key.json', 'onboarding.json']) expect(reservedKeys(readFileSync(join(SAMPLE_ROOT, folder, f), 'utf8')), `${folder} ${f}`).toEqual([])
  })

  test('ARC-8 each name is found at the root, in a nested object and in an object inside an array, in written order', async () => {
    const { reservedKeys } = await scanners()
    for (const name of NAMES) {
      const k = JSON.stringify(name)
      expect(keysOf(reservedKeys(`{${k}: 1}`)), `${name} at the root`).toEqual([name])
      expect(keysOf(reservedKeys(`{"a": {"b": {${k}: {}}}}`)), `${name} nested`).toEqual([name])
      expect(keysOf(reservedKeys(`{"a": [1, {"x": 2, ${k}: [3]}]}`)), `${name} in an array`).toEqual([name])
    }
    expect(keysOf(reservedKeys('{"prototype": 1, "a": {"__proto__": 2}, "b": [{"constructor": 3}], "c": {"constructor": 4}}'))).toEqual(['prototype', '__proto__', 'constructor', 'constructor'])
  })

  test('ARC-8 an escaped spelling is the same key; a value, a longer key and a repeated ordinary key are not reserved', async () => {
    const { reservedKeys, repeatedKeys } = await scanners()
    expect(keysOf(reservedKeys('{"\\u005f\\u005fproto\\u005f\\u005f": 1}'))).toEqual(['__proto__'])
    expect(keysOf(reservedKeys('{"\\u0063onstructor": 1}'))).toEqual(['constructor'])
    expect(reservedKeys('{"a": "__proto__", "b": ["constructor", "prototype"], "c": "{\\"__proto__\\": 1}"}')).toEqual([])
    expect(reservedKeys('{"__proto__x": 1, "my_constructor": 2, "prototypes": 3, "Constructor": 4}')).toEqual([])
    expect(reservedKeys('{"a": 1, "a": 2}')).toEqual([])
    expect(keysOf(repeatedKeys('{"__proto__": 1, "__proto__": 2}')), 'repeatedKeys still finds a repeat of any key').toEqual(['__proto__'])
  })

  test('ARC-8 every object node of every onboarding.json, given a "constructor" key first, is found once', async () => {
    const { reservedKeys } = await scanners()
    for (const c of clients) {
      const text = readFileSync(join(SAMPLE_ROOT, c.folder, 'onboarding.json'), 'utf8')
      const json = JSON.parse(text) as unknown
      for (const n of objectNodes(json)) {
        const copy = structuredClone(json)
        let node: unknown = copy
        for (const s of n.path) node = (node as Record<string | number, unknown>)[s]
        const hole = 'w00c_reserved_hole_(Test)'
        ;(node as Record<string, unknown>)[hole] = 0
        const planted = JSON.stringify(copy).replace(JSON.stringify(hole), '"constructor"')
        expect(keysOf(reservedKeys(planted)), `${c.id} onboarding.json at ${n.path.join('.') || '(root)'}`).toEqual(['constructor'])
      }
    }
  })

  // Spec review 4, gap 3: the onboarding walk reaches depth 5 only; answer keys go deeper. For each object path of the
  // answer keys (array indexes as [], statementBalances account keys and trial balance names as "*"), the first node of
  // the first folder that has it is given each name as a key.
  const keyPaths = (() => {
    const out = new Map<string, { id: string; folder: string; path: readonly (string | number)[] }>()
    for (const c of clients) {
      const json = JSON.parse(readFileSync(join(SAMPLE_ROOT, c.folder, 'answer-key.json'), 'utf8')) as unknown
      for (const n of objectNodes(json)) {
        const label = pattern(genericOf(n.path))
        if (!out.has(label)) out.set(label, { id: c.id, folder: c.folder, path: n.path })
      }
    }
    return [...out]
  })()

  test('ARC-8 the walk finds the answer-key object paths (88 on the spec probe, path depth up to 6; never fewer)', () => {
    expect(keyPaths.length).toBeGreaterThanOrEqual(88)
    expect(Math.max(...keyPaths.map(([, n]) => n.path.length))).toBeGreaterThanOrEqual(6)
  })

  test.each(keyPaths.map(([label, n]): [string, string, readonly (string | number)[], string] => [label === '' ? '(top)' : label, n.id, n.path, n.folder]))(
    'ARC-8 answer-key.json %s (first in %s): each reserved name written as a key of that object is found once',
    async (_label, id, path, folder) => {
      const { reservedKeys } = await scanners()
      const json = JSON.parse(readFileSync(join(SAMPLE_ROOT, folder, 'answer-key.json'), 'utf8')) as unknown
      let node: unknown = json
      for (const s of path) node = (node as Record<string | number, unknown>)[s]
      const hole = 'w00c_reserved_hole_(Test)'
      ;(node as Record<string, unknown>)[hole] = 0
      const text = JSON.stringify(json)
      for (const name of NAMES) {
        const planted = text.replace(JSON.stringify(hole), JSON.stringify(name))
        expect(keysOf(reservedKeys(planted)), `${id} answer-key.json at ${path.join('.') || '(root)'} with "${name}"`).toEqual([name])
      }
    },
    30_000,
  )
})

testworld/model/links.acceptance.test.ts.source:
// W00c acceptance tests (round 2), RC4: file checks look at what a name resolves to, not at the written name
// (reports/W00c-findings.md, fix 4 and "Acceptance tests for the spec writer").
//
// Every case comes from the walk over all numbered folders of reference/sample-clients/ (sample-walk.ts and
// w00c-walk.ts), never from a typed list. Each plants one link in a temp copy and loads through the public loader.
//
// What the W00c round 2 build does (guardFiles, W00b's region, is not touched):
//   answer-key.json and onboarding.json are read only when they are regular files themselves (lstat): a link is a
//   'file' issue naming the file, even when it leads to a valid copy.
//   An account file: its real path, relative to the client folder's real path, must itself be `<dir>/<name>.csv`
//   (accounts/ for `file`, qbo/ for `qboFile`) and a regular file; otherwise a 'file' issue naming the account key
//   and the field. A link inside the same subfolder to one of its own CSVs is still fine (load-files.test.ts).
//   A client folder that is itself a link (lstat) is not listed by clientFolders, and loading its id is a
//   TestWorldLoadError with a 'file' issue naming the folder (spec review 3, gap 2; amber: "refused by clientFolders"
//   read as "not listed", since the other folders must still list); every other folder still lists and loads.
import { join } from 'node:path'
import { afterAll, afterEach, describe, expect, test } from 'vitest'
import { clientFolders } from '../index'
import { Sandbox, expectLoads, refusal, walkClients, type RawAccount, type WalkClient } from './__fixtures__/sample-walk'
import { Planter, expectNamed } from './__fixtures__/w00c-walk'

const clients = walkClients()
const sb = new Sandbox()
const planter = new Planter(sb)
afterEach(() => {
  planter.undo()
  sb.restore()
})
afterAll(() => {
  sb.dispose()
})

type AccountCase = { c: WalkClient; a: RawAccount; i: number }
const byId = (cs: WalkClient[]): [string, WalkClient][] => cs.map((c): [string, WalkClient] => [c.id, c])
const withAccounts = clients.filter((c) => c.key.accounts.length > 0)
const accountCases: [string, AccountCase][] = withAccounts.flatMap((c) => c.key.accounts.map((a, i): [string, AccountCase] => [`${c.id} ${a.key}`, { c, a, i }]))
const base = (rel: string): string => rel.slice(rel.lastIndexOf('/') + 1)

/** Points the account's field at a new name in the copy's answer key. */
function point(c: WalkClient, a: RawAccount, i: number, field: 'file' | 'qboFile', name: string): void {
  sb.editKey(c, (k) => {
    const acc = k.accounts[i]
    if (acc?.key !== a.key) throw new Error(`fixture: account ${a.key} moved`)
    acc[field] = name
  })
}

describe('W00c RC4 the walk', () => {
  test('ARC-8 the walk finds account files under accounts/ and qbo/ in every folder with accounts', () => {
    expect(accountCases.length).toBeGreaterThan(0)
    for (const [label, { a }] of accountCases) {
      expect(a.file, label).toMatch(/^accounts\/[^/]+\.csv$/)
      expect(a.qboFile, label).toMatch(/^qbo\/[^/]+\.csv$/)
    }
  })
})

describe('W00c RC4 an account file is checked where it resolves (every account of every folder)', () => {
  test.each(accountCases)("ARC-8 %s file set to accounts/zz-(Test).csv, a link to ../answer-key.json, is refused with a 'file' issue naming the account and the field", async (_l, { c, a, i }) => {
    planter.link(c, 'accounts/zz-(Test).csv', '../answer-key.json')
    point(c, a, i, 'file', 'accounts/zz-(Test).csv')
    expectNamed(await refusal(sb, c.id), 'file', [a.key, 'file'])
  })

  test.each(accountCases)("ARC-8 %s file set to accounts/x-(Test).csv, a link to its own qbo CSV, is refused with a 'file' issue naming the account and the field", async (_l, { c, a, i }) => {
    planter.link(c, 'accounts/x-(Test).csv', `../${a.qboFile}`)
    point(c, a, i, 'file', 'accounts/x-(Test).csv')
    expectNamed(await refusal(sb, c.id), 'file', [a.key, 'file'])
  })

  test.each(accountCases)("ARC-8 %s qboFile set to qbo/x-(Test).csv, a link to its own accounts CSV, is refused with a 'file' issue naming the account and the field", async (_l, { c, a, i }) => {
    planter.link(c, 'qbo/x-(Test).csv', `../${a.file}`)
    point(c, a, i, 'qboFile', 'qbo/x-(Test).csv')
    expectNamed(await refusal(sb, c.id), 'file', [a.key, 'qboFile'])
  })

  test.each(accountCases)('ARC-8 %s file set to accounts/inside-(Test).csv, a link to its own CSV in the same folder, still loads', async (_l, { c, a, i }) => {
    planter.link(c, 'accounts/inside-(Test).csv', base(a.file))
    point(c, a, i, 'file', 'accounts/inside-(Test).csv')
    await expectLoads(sb, c.id)
  })
})

describe('W00c RC4 a subfolder that is itself a link is refused for every account file in it (every folder with accounts)', () => {
  const cases = withAccounts.flatMap((c) => (['accounts', 'qbo'] as const).map((dir): [string, 'accounts' | 'qbo', WalkClient] => [c.id, dir, c]))

  test.each(cases)("ARC-8 %s with %s/ a link to a renamed copy of itself is refused with a 'file' issue for every account, naming the field", async (_l, dir, c) => {
    planter.folderAsLink(c, dir)
    const issues = await refusal(sb, c.id)
    const field = dir === 'accounts' ? 'file' : 'qboFile'
    for (const a of c.key.accounts) expectNamed(issues, 'file', [a.key, field])
  })
})

describe('W00c RC4 the client JSON files are regular files, never links (every folder)', () => {
  const cases = clients.flatMap((c) => (['answer-key.json', 'onboarding.json'] as const).map((name): [string, string, WalkClient] => [c.id, name, c]))

  test.each(cases)("ARC-8 %s with %s a link to a byte-for-byte copy outside the folder is refused with a 'file' issue naming the file", async (_l, name, c) => {
    planter.linkToOutsideCopy(c, name)
    expectNamed(await refusal(sb, c.id), 'file', [name])
  })

  test.each(byId(clients))('END-9 %s loads unchanged (no link anywhere in the sample folders)', async (_l, c) => {
    await expectLoads(sb, c.id)
  })
})

describe('W00c RC4 a client folder that is itself a link is refused (spec review 3, gap 2: every folder)', () => {
  test.each(byId(clients))("ARC-8 %s with its client folder a link to a renamed copy beside it is not listed by clientFolders, and its load is refused with a 'file' issue naming the folder", async (_l, c) => {
    planter.clientFolderAsLink(c)
    const listed = clientFolders(sb.root)
    expect(listed.has(c.id as `C${string}`), `${c.id} is a link and must not be listed`).toBe(false)
    expect(listed.size).toBe(clients.length - 1)
    for (const o of clients.filter((x) => x !== c)) expect(listed.get(o.id as `C${string}`), o.id).toBe(join(sb.root, o.folder))
    expectNamed(await refusal(sb, c.id), 'file', [c.folder])
  })

  test.each(byId(clients))('END-9 with %s a linked client folder, every other folder still loads', async (_l, c) => {
    planter.clientFolderAsLink(c)
    for (const o of clients.filter((x) => x !== c)) await expectLoads(sb, o.id)
   }, 30_000)
})

testworld/clients/json-keys.acceptance.t.source:
// W00c acceptance tests (round 2 spec patch, reports/W00c-spec-review-3.md gap 3): the repeated-key scanner is a pure
// function exported from testworld/clients/json-keys.ts, so W00b (kind .json files) imports the same one.
//
// What the W00c round 2 build provides:
//   `repeatedKeys(text: string): readonly { key: string }[]` (more fields allowed): every key written twice in one
//   object of the JSON text, at any depth, compared after JSON string escapes are decoded; [] when there is none. Equal
//   keys in different objects are not repeats, and text inside a string value is never a key. The loader turns each one
//   into a 'file' issue naming the file and the key (testworld/model/json-keys.acceptance.test.ts).
//
// Every case comes from the walk over all numbered folders of reference/sample-clients/ (sample-walk.ts), never from a
// typed list: every object node of every onboarding.json, and in every answer-key.json one node per depth present plus
// 30 more, picked with fast-check seed 20261003. The module is loaded by a dynamic import so the suite type-checks before
// the build; until then each test fails with "Cannot find module".
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import fc from 'fast-check'
import { describe, expect, test } from 'vitest'
import { SAMPLE_ROOT, walkClients, type WalkClient } from '../model/__fixtures__/sample-walk'
import { objectNodes, repeatFirstKey, sampleNodes, type ObjectNode } from '../model/__fixtures__/w00c-walk'

type RepeatedKeys = (text: string) => readonly { key: string }[]
async function scanner(): Promise<RepeatedKeys> {
  const specifier = './json-keys'
  const mod = (await import(/* @vite-ignore */ specifier)) as { repeatedKeys?: unknown }
  expect(typeof mod.repeatedKeys, 'testworld/clients/json-keys.ts exports repeatedKeys').toBe('function')
  return mod.repeatedKeys as RepeatedKeys
}

const SEED = 20261003
const pick = (n: number, seed: number): number => fc.sample(fc.integer({ min: 0, max: n - 1 }), { seed, numRuns: 1 })[0] ?? 0
const clients = walkClients()
const FILES = ['answer-key.json', 'onboarding.json'] as const
const textOf = (c: WalkClient, name: string): string => readFileSync(join(SAMPLE_ROOT, c.folder, name), 'utf8')
const byId = (cs: WalkClient[]): [string, WalkClient][] => cs.map((c): [string, WalkClient] => [c.id, c])
const keysOf = (found: readonly { key: string }[]): string[] => found.map((r) => r.key)

describe('W00c RC5 the scanner on the sample files as written', () => {
  test.each(byId(clients))('END-9 %s has no repeated key in answer-key.json or onboarding.json', async (_l, c) => {
    const repeatedKeys = await scanner()
    for (const name of FILES) expect(repeatedKeys(textOf(c, name)), `${c.id} ${name}`).toEqual([])
  })
})

describe('W00c RC5 the scanner finds a repeated key in every object of every onboarding.json', () => {
  const cases = clients.map((c): [string, number, { c: WalkClient; nodes: ObjectNode[] }] => {
    const nodes = objectNodes(JSON.parse(textOf(c, 'onboarding.json')) as unknown)
    return [c.id, nodes.length, { c, nodes }]
  })

  test.each(cases)('ARC-8 %s: each of its %i object nodes, written with its first key twice (a decoy first), is found with that key', async (_l, _n, { c, nodes }) => {
    const repeatedKeys = await scanner()
    expect(nodes.length).toBeGreaterThan(0)
    const json = JSON.parse(textOf(c, 'onboarding.json')) as unknown
    for (const n of nodes) {
      const { text, key } = repeatFirstKey(json, n.path)
      expect(JSON.parse(text), 'fixture: a last-wins parse gives back the original').toEqual(json)
      expect(keysOf(repeatedKeys(text)), `${c.id} onboarding.json at ${n.path.join('.') || '(root)'}`).toContain(key)
    }
  })
})

describe('W00c RC5 the scanner finds a repeated key at every depth of every answer-key.json (pinned-seed sample)', () => {
  const cases = clients.map((c, ci): [string, { c: WalkClient; nodes: ObjectNode[]; all: ObjectNode[] }] => {
    const all = objectNodes(JSON.parse(textOf(c, 'answer-key.json')) as unknown)
    return [c.id, { c, all, nodes: sampleNodes(all, SEED + ci * 100, 30, pick) }]
  })

  test.each(cases)('ARC-8 %s: one object node per depth present and 30 more, each written with its first key twice (a decoy first), is found with that key', async (_l, { c, nodes, all }) => {
    const repeatedKeys = await scanner()
    expect(new Set(nodes.map((n) => n.depth))).toEqual(new Set(all.map((n) => n.depth)))
    const json = JSON.parse(textOf(c, 'answer-key.json')) as unknown
    for (const n of nodes) {
      const { text, key } = repeatFirstKey(json, n.path)
      expect(keysOf(repeatedKeys(text)), `${c.id} answer-key.json at ${n.path.join('.') || '(root)'}`).toContain(key)
    }
  }, 30_000)
})

describe('W00c RC5 what the scanner must not call a repeat, and escapes', () => {
  test('ARC-8 equal keys in sibling and nested objects are not repeats', async () => {
    const repeatedKeys = await scanner()
    expect(repeatedKeys('{"a": {"a": 1, "b": {"a": 2}}, "b": [{"a": 1}, {"a": 2}]}')).toEqual([])
  })

  test('ARC-8 text inside a string value is never a key, even with escaped quotes and a trailing backslash', async () => {
    const repeatedKeys = await scanner()
    expect(repeatedKeys(JSON.stringify({ a: 'x", "a": 1, "b": "y (Test)', b: ['c\\', '"a": 2 \\" "a": 3 (Test)'] }))).toEqual([])
  })

  test('ARC-8 a key written once plain and once with a unicode escape is a repeat, named decoded', async () => {
    const repeatedKeys = await scanner()
    expect(keysOf(repeatedKeys('{"x": [{"amount": 0, "am\\u006funt": 1}]}'))).toEqual(['amount'])
  })

  test('ARC-8 a repeat deep inside arrays of objects is found with its key', async () => {
    const repeatedKeys = await scanner()
    expect(keysOf(repeatedKeys('{"t": [[{"lines": [{"debit": 0, "credit": 1, "debit": 2}]}]]}'))).toEqual(['debit'])
  })
})

